import {CREATURES,AREAS,ELEMENTS,MOVES} from './data.mjs';
import {newGame,act,stats,matchup,captureChance,availableMoves,serialize,validateSave,loadSave,saveGame,SAVE_KEY} from './core.mjs';
import {creatureArt,mapArt} from './art.mjs';

const $=s=>document.querySelector(s), root=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{}
const loaded=loadSave(storage);
let state=loaded.state, tab='world', paused=false, sound=false, audio=null, pendingImport=null, pendingRelease=null, modal=null, notice=loaded.error||'', saved=!!state, lastAction=-Infinity, conflict=false;
const creature=id=>CREATURES.find(c=>c.id===id)||CREATURES[0];
const area=id=>AREAS.find(a=>a.id===id)||AREAS[0];
const btn=(action,label,attrs='',cls='')=>`<button type="button" data-action="${action}" ${attrs} class="${cls}">${label}</button>`;
function art(id,size=160){return `<div class="creature-image">${creatureArt(id,{size})}</div>`;}
function hp(c){return `<progress class="hp" aria-label="${esc(creature(c.species).name)}體力" max="${stats(c).maxHp}" value="${c.hp}"></progress>`;}
function persist(){if(conflict)return;const result=saveGame(storage,state);saved=result.ok;if(!result.ok)notice=result.error||'無法儲存；請匯出備份。';}
function tone(){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(440,audio.currentTime);o.frequency.exponentialRampToValueAtTime(660,audio.currentTime+.07);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.16);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.17);}catch{sound=false;notice='此瀏覽器無法播放音效。';}}
function questHint(){if(state.flags.ending)return '星潮重現。繼續探索，找齊 12 種靈獸吧。';if(!state.flags.forest)return `前往${area('forest').name}，點亮第一座信標。`;if(!state.flags.coast)return `前往${area('coast').name}，喚醒第二座信標。`;if(!state.flags.quarry)return `前往${area('quarry').name}，修復第三座信標。`;return `三盞燈已亮起。前往${area('summit').name}，面對迷失的守望者。`;}
function header(){return `<header class="topbar"><div class="brand"><span class="brand-icon" aria-hidden="true">✦</span><div><strong>安東尼大冒險</strong><small>THE STARLIGHT ISLES · 星潮群島</small></div></div><div class="header-tools"><span class="save-indicator ${saved?'':'save-error'}">${state?(saved?'● 進度已自動儲存':'○ 尚未儲存'):'一段屬於你的冒險'}</span>${btn('sound',sound?'♫ 音效開':'♪ 靜音',`aria-pressed="${sound}" aria-label="${sound?'關閉音效':'開啟音效'}"`,'quiet')}${state?btn('pause','Ⅱ 暫停','','quiet'):''}</div></header>`;}
function welcome(){return `<main id="main"><section class="welcome"><div class="welcome-copy"><span class="eyebrow">一場關於相遇與勇氣的旅程</span><h1>帶上夥伴，<br>把星光找回來。</h1><p>星潮退去的那一夜，群島的三座信標熄滅了。現在，輪到安東尼與靈獸一起穿過森林、海岸與礦谷，解開山巔的祕密。</p></div><div class="welcome-art" aria-hidden="true">${mapArt('town',4,4,{})}</div></section><div class="starter-title"><h2>選擇你的第一位夥伴</h2><small>其餘夥伴可在旅途中遇見</small></div><div class="starter-grid">${CREATURES.slice(0,3).map((c,i)=>`<button class="starter" data-action="start" data-id="${c.id}">${art(c.id,170)}<span class="tag">0${i+1} / ${esc(ELEMENTS[c.element].name)}屬性</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><span class="choose">就決定一起冒險了 →</span></button>`).join('')}</div><p class="intro-note">點按方向鍵移動 · 回合制戰鬥，慢慢想也沒關係 · 自動儲存於此瀏覽器</p><div class="settings-actions">${btn('openSettings','匯入已有冒險 / 遊玩說明','','quiet')}</div></main>`;}
function resources(){return `<div class="resource-row"><span>◈ ${state.coins} 星幣</span><span>◎ ${state.inventory.orbs} 星環</span><span>✚ ${state.inventory.potions} 藥露</span></div>`;}
function sidebar(){return `<aside class="side"><section class="panel"><span class="eyebrow">YOUR JOURNEY</span><h3 class="spacer">讓群島再次發光</h3>${['forest','coast','quarry'].map((id,i)=>`<div class="quest-step"><span class="step-dot ${state.flags[id]?'done':''}">${state.flags[id]?'✓':i+1}</span><span>${esc(area(id).name)}信標</span></div>`).join('')}<p class="hint">${questHint()}</p></section><section class="panel party-panel"><span class="eyebrow">TRAVEL COMPANIONS</span><h3 class="spacer">同行夥伴 <small>${state.team.length} / 3</small></h3>${state.team.map(c=>`<div class="member-mini">${creatureArt(c.species,{size:54})}<div class="grow"><strong>${esc(creature(c.species).name)}</strong> <small>Lv.${c.level}</small>${hp(c)}</div></div>`).join('')}</section><section class="panel"><span class="eyebrow">TRAVEL NOTES</span><p class="hint spacer">弱化並降低野生靈獸的體力，能提高捕捉機率。守護者蓄力時先防守；隨時回港免費休息。</p><p class="hint">捕捉與勝利都能獲得經驗。低等級夥伴會加速成長。</p></section></aside>`;}
function navigation(){return `<nav class="tabs" aria-label="冒險選單">${[['world','⌘ 探索'],['team','♧ 夥伴'],['journal','✧ 手記'],['settings','⚙ 備份']].map(([id,label])=>`<button data-tab="${id}" ${tab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;}
function world(){if(state.battle)return battle();const a=area(state.area);return `${state.flags.ending?`<section class="ending"><div class="star">✦</div><span class="eyebrow">冒險第一章 · 完</span><h2>星光，因你們而重現。</h2><p>守望者終於聽見夥伴們的呼喚。三道光穿過夜空，連起每一座島嶼。安東尼知道，勇敢從來不是獨自前行，而是願意伸出手。</p><p>明天，還有新的相遇。</p><span class="pill">已完成主線 · ${state.caught.length} / 12 種夥伴</span></section>`:''}<section class="map-card"><div class="map-heading"><div><span class="eyebrow">${state.area==='town'?'HOME SWEET HOME':'EXPLORE THE ISLES'}</span><h2>${esc(a.name)}</h2></div><span class="pill">${state.area==='town'?'安全區域':`探索等級 ${a.level}`}</span></div><div class="map-scene" id="map" aria-label="${esc(a.name)}地圖，位置 ${state.x+1},${state.y+1}">${mapArt(state.area,state.x,state.y,state.flags)}<span class="map-caption">${esc(a.description)}</span></div><div class="world-controls"><div class="dpad" aria-label="移動控制"><button data-dir="up" aria-label="向上移動">↑</button><button data-dir="left" aria-label="向左移動">←</button><button data-dir="down" aria-label="向下移動">↓</button><button data-dir="right" aria-label="向右移動">→</button></div><div><div class="world-actions">${state.area==='town'?btn('heal','✚ 免費休息','','primary')+btn('talk','與港長聊聊','data-id="elder"'):btn('explore','⌕ 尋找靈獸','','primary')+btn('gather','❋ 尋找星草')+btn('challenge',state.area==='summit'?'✦ 挑戰守望者':state.flags[state.area]?'✓ 重訪信標':'✦ 信標試煉')}</div><p class="hint">點按方向移動，也可使用方向鍵 / WASD</p></div></div></section><div class="route-list" aria-label="地區旅行">${AREAS.map(a=>btn('travel',`${a.requires&&!state.flags[a.requires]?'🔒 ':''}${esc(a.name)}`,`data-id="${a.id}" ${a.requires&&!state.flags[a.requires]?'disabled':''}`,a.id===state.area?'selected':'')).join('')}</div>${state.area==='town'?`<section class="panel spacer"><div class="section-title"><h3>港邊補給站</h3><small>每次遠行前，準備一下</small></div>${resources()}<div class="npc-buttons">${btn('buy','星環 · 12 星幣','data-id="orbs"')}${btn('buy','藥露 · 18 星幣','data-id="potions"')}${btn('talk','採集員的委託','data-id="ranger"')}${btn('talk','收藏家的委託','data-id="collector"')}</div><p class="hint">免費休息會恢復全隊，並補足基本星環。失敗不會失去夥伴。</p></section>`:resources()}`;}
function battle(){const b=state.battle,c=state.team[state.active],e=b.enemy,def=creature(e.species),own=creature(c.species),rate=Math.round(captureChance(state)*100);return `<section class="battle"><div class="battle-top"><div><span class="eyebrow">${b.kind==='wild'?'A NEW ENCOUNTER':b.kind==='boss'?'THE LAST LIGHT':'BEACON TRIAL'}</span><h2>${b.kind==='wild'?'草叢裡的相遇':b.kind==='boss'?'星隕守望者':'信標守護者'}</h2></div><span class="pill">回合 ${b.turn}</span></div><div class="battle-stage"><div class="combatant ally"><div class="stat-line"><strong>${esc(own.name)}</strong><small>Lv.${c.level}</small></div>${hp(c)}<small>${c.hp} / ${stats(c).maxHp} · ${esc(ELEMENTS[own.element].name)}</small>${art(c.species,190)}</div><div class="combatant enemy">${art(e.species,190)}<div class="stat-line"><strong>${b.kind==='boss'?'迷失的 ':''}${esc(def.name)}</strong><small>Lv.${e.level}</small></div>${hp(e)}<small>${e.hp} / ${stats(e).maxHp} · ${esc(ELEMENTS[def.element].name)}${b.weakened?' · 已弱化':''}</small></div></div><div class="intent">${b.result?'這次相遇，為旅程添上新的一頁。':b.intent==='heavy'?'⚠ 強力攻擊即將來襲！使用「防守」大幅減傷。':b.intent==='charge'?'✧ 對手正在蓄力，趁機調整隊伍或恢復體力。':'對手準備進攻。觀察屬性，再決定下一步。'}</div><div class="battle-log" aria-live="polite">${b.log.slice(-3).map(l=>`<p>${esc(l)}</p>`).join('')}</div>${b.result?`<div class="result"><h2>${{won:'勝利！信任讓你們更強。',caught:'新的夥伴，歡迎加入！',escaped:'平安離開，整裝再出發。',lost:'先休息一下，再一起出發。'}[b.result]}</h2>${btn('closeBattle',b.result==='lost'?'返回星燈港 · 免費恢復':'繼續冒險 →','','primary')}</div>`:`<div class="battle-actions">${btn('attack','輕撞<small>穩定的普通攻擊</small>','data-move="0"')}${btn('attack',`屬性共鳴<small>${matchup(own.element,def.element)>1?'效果絕佳':matchup(own.element,def.element)<1?'對手抗性':'正常效果'} ×${matchup(own.element,def.element)}</small>`,'data-move="1"','primary')}${btn('guard','防守<small>減輕下一次傷害</small>')}${btn('focus','安撫弱化<small>提高捕捉機率</small>',b.kind!=='wild'?'disabled':'')}${btn('capture',`星環捕捉<small>${rate}% 機率 · 剩 ${state.inventory.orbs}</small>`,b.kind!=='wild'||!state.inventory.orbs?'disabled':'')}${btn('potion',`使用藥露<small>剩 ${state.inventory.potions} 瓶</small>`,!state.inventory.potions?'disabled':'')}${c.level>=7?btn('attack','回春<small>每場戰鬥限兩次</small>','data-move="2"'):''}${btn('run','離開戰鬥<small>保留體力，稍後再來</small>')}</div><div class="battle-switch">${state.team.map((m,i)=>i!==state.active?btn('switch',`換上 ${esc(creature(m.species).name)} · ${m.hp} HP`,`data-index="${i}" ${m.hp<=0?'disabled':''}`):'').join('')}</div>`}</section>`;}
function card(c,index,reserve=false){const def=creature(c.species);return `<article class="creature-card">${art(c.species,140)}<span class="tag">${esc(ELEMENTS[def.element].name)}屬性 · Lv.${c.level} · ${esc(def.role)}</span><h3>${esc(def.name)}</h3>${hp(c)}<p>體力 ${c.hp} / ${stats(c).maxHp} · 經驗 ${c.xp}</p><p>${esc(def.description)}</p><p>招式：輕撞、屬性共鳴${c.level>=7?'、回春':'（Lv.7 學會回春）'}</p>${reserve?btn('swapReserve','與領隊交換',`data-index="${index}" ${state.battle?'disabled':''}`)+btn('release','讓牠回到野外',`data-uid="${esc(c.uid)}" ${state.battle?'disabled':''}`,'quiet danger'):btn('lead',index===state.active?'目前領隊':'設為領隊',`data-index="${index}" ${index===state.active||state.battle||c.hp<=0?'disabled':''}`)}</article>`;}
function team(){return `<div class="section-title"><h2>同行的夥伴</h2><span class="pill">${state.team.length} / 3</span></div><p class="hint">領隊先出戰，戰鬥中可以換人。後備夥伴的經驗也會成長。</p><div class="cards spacer">${state.team.map((c,i)=>card(c,i)).join('')}</div><h2 class="spacer">港口後備隊 <small>${state.reserve.length} / 40</small></h2>${state.reserve.length?`<div class="cards">${state.reserve.map((c,i)=>card(c,i,true)).join('')}</div>`:'<div class="panel empty">隊伍滿員後，新夥伴會在這裡等你。</div>'}`;}
function journal(){return `<div class="section-title"><h2>星潮冒險手記</h2><span class="pill">收集 ${state.caught.length} / 12</span></div><div class="card-grid"><section class="panel"><span class="eyebrow">MAIN QUEST</span><h3 class="spacer">失落的三道光</h3><p>${questHint()}</p><p>守護者蓄力後會使出重擊。帶上相剋的夥伴，觀察提示並防守，就能讓信標再次甦醒。</p></section><section class="panel"><span class="eyebrow">SIDE QUESTS</span><h3 class="spacer">港口的約定</h3><p>採集員：收集 3 株星草（${state.quests.herbs} / 3）${state.quests.herbsClaimed?' · 已領獎':''}<br>收藏家：遇見 5 種夥伴（${state.caught.length} / 5）${state.quests.capturesClaimed?' · 已領獎':''}</p><p>在野外尋找星草，捕捉不同靈獸，再回港交付。早已完成的目標也會計算。</p></section></div><section class="panel spacer"><h3>元素相剋筆記</h3><p class="hint">屬性共鳴會受相剋影響，輕撞則維持普通傷害。下列為攻擊效果絕佳的組合。</p><table class="help-table"><thead><tr><th>攻擊屬性</th><th>對手屬性</th><th>效果</th></tr></thead><tbody>${Object.entries(ELEMENTS).map(([id,v])=>`<tr><td>${esc(v.name)}</td><td>${Object.entries(ELEMENTS).filter(([other])=>matchup(id,other)>1).map(([,o])=>esc(o.name)).join('、')}</td><td>×${Math.max(...Object.keys(ELEMENTS).map(o=>matchup(id,o)))}</td></tr>`).join('')}</tbody></table></section><h2 class="spacer">靈獸圖鑑</h2><div class="cards">${CREATURES.map(c=>`<article class="creature-card">${state.seen.includes(c.id)||state.caught.includes(c.id)?art(c.id,130):'<div class="empty">✧<br>尚未相遇</div>'}<span class="tag">${state.caught.includes(c.id)?'已成為夥伴':state.seen.includes(c.id)?'曾經遇見':'等待發現'}</span><h3>${state.seen.includes(c.id)||state.caught.includes(c.id)?esc(c.name):'未知的靈獸'}</h3><p>${state.caught.includes(c.id)?esc(c.description):'繼續探索群島，讓下一次相遇發生。'}</p></article>`).join('')}</div>`;}
function settings(){return `<section class="panel"><span class="eyebrow">KEEP YOUR ADVENTURE SAFE</span><h2 class="spacer">備份與遊玩說明</h2><p class="muted">每次操作後自動存檔，並保留上一份有效備份。瀏覽器資料遭清除、無痕模式或換手機時，進度可能遺失；請定期匯出。</p><div class="settings-actions">${btn('export','↓ 匯出冒險存檔',!state?'disabled':'','primary')}<label class="file-label">↑ 匯入存檔<input id="import-file" type="file" accept=".json,application/json" aria-label="匯入存檔"></label>${state?btn('new','重新開始','','danger'):btn('backWelcome','選擇夥伴')}</div><p class="hint">只接受此遊戲的 JSON 備份（上限 150 KB）。匯入前會檢查，確認後才取代目前進度。</p></section><section class="panel spacer"><h3>給新冒險者的小指南</h3><p>① 選一位夥伴，從星燈港前往森林。點按方向鍵走動，或按「尋找靈獸」主動探索。<br>② 戰鬥一回合做一次決定：攻擊、防守、換人、用藥或捕捉。先降低對手體力，再「安撫弱化」，更容易成為夥伴。<br>③ 挑戰各區的信標守護者，解鎖下一個區域。蓄力提示出現後，要留意下一回合的重擊。<br>④ 隨時回港免費休息、補充基本星環，接下兩份支線委託。全隊倒下也能回港重新出發。<br>⑤ 三盞信標亮起後，登上山巔。結局之後，仍能自由探索並收集所有夥伴。</p><p class="hint">桌面支援方向鍵 / WASD。手機輕點方向鍵；遊戲控制鍵不會因連點放大，其他內容仍支援縮放。切到其他 app 時會自動暫停，回來後按「繼續冒險」。音效預設關閉。</p><p class="hint">所有故事、靈獸與圖像皆為原創。本遊戲無帳戶、廣告、付費服務或外部 API。首次載入需要網路或本機伺服器；不保證離線快取。</p></section>`;}
function overlay(){if(modal==='release'&&!paused&&pendingRelease)return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="release-title"><h2 id="release-title">讓這位夥伴回到野外？</h2><p>後備隊的 ${esc(creature(pendingRelease.species).name)} · Lv.${pendingRelease.level} 將離開隊伍，無法復原。圖鑑紀錄會保留，同行夥伴不受影響。</p><div class="settings-actions">${btn('cancel','保留夥伴','','primary')}${btn('confirmRelease','確認放生這位後備夥伴','','danger')}</div></section></div>`;if(paused)return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="pause-title"><span class="eyebrow">TAKE A BREATH</span><h2 id="pause-title" class="spacer">星光會在這裡等你。</h2><p>冒險已暫停。沒有計時壓力，準備好再出發。</p>${btn('resume','繼續冒險','','primary')}</section></div>`;if(modal==='import')return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="import-title"><h2 id="import-title">載入這段冒險？</h2><p>${pendingImport.caught.length} 種夥伴 · ${esc(area(pendingImport.area).name)} · ${pendingImport.flags.ending?'已完成主線':'冒險進行中'}</p><p>確認後會取代目前進度。你可以先取消並匯出目前存檔。</p><div class="settings-actions">${btn('confirmImport','確認匯入','','primary')}${btn('cancel','取消')}</div></section></div>`;if(modal==='new')return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="new-title"><h2 id="new-title">開始另一段冒險？</h2><p>目前進度將被新的冒險取代。建議先匯出備份。</p><div class="settings-actions">${btn('confirmNew','確定重新開始','','danger')}${btn('cancel','保留目前冒險')}</div></section></div>`;return '';}
function render(){const before=document.activeElement;const focusKey=before?.dataset?.action,focusId=before?.dataset?.id;root.innerHTML=`<div class="shell">${header()}${notice?`<p class="message save-error" role="status">${esc(notice)}</p>`:''}${!state?(tab==='settings'?`<main id="main">${settings()}</main>`:welcome()):`<div class="layout"><main id="main">${navigation()}${state.message&&!(state.battle&&tab==='world'&&state.message===state.battle.log.at(-1))?`<div class="message" id="story-message">${esc(state.message)}</div>`:''}${tab==='world'?world():tab==='team'?team():tab==='journal'?journal():settings()}</main>${sidebar()}</div>`}<footer class="footer"><span>✦ 星潮群島 · 每一段冒險，都從相遇開始</span><a href="../">返回 Demo 首頁 ↗</a></footer></div>${overlay()}`;if(paused||modal){$('.modal button')?.focus();}else if(focusKey){const candidate=[...root.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusKey&&el.dataset.id===focusId);candidate?.focus({preventScroll:true});}}
function dispatch(action){if(!state||paused||modal||conflict)return;const now=performance.now();if(now-lastAction<280)return;lastAction=now;state=act(state,action);persist();tone();render();$('#announcement').textContent=state.message||state.battle?.log.at(-1)||'';}
const directions={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
function move(dir){if(tab!=='world'||state?.battle)return;const [dx,dy]=directions[dir];dispatch({type:'move',dx,dy});}
root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||button.disabled)return;if(button.dataset.tab){if(paused||modal)return;tab=button.dataset.tab;render();return;}if(button.dataset.dir){move(button.dataset.dir);return;}const a=button.dataset.action,id=button.dataset.id,index=Number(button.dataset.index);if(a==='sound'){sound=!sound;if(sound)tone();else audio?.suspend();render();return;}if(a==='pause'){paused=true;audio?.suspend();render();return;}if(a==='resume'){if(conflict){location.reload();return;}paused=false;render();return;}if(a==='cancel'){modal=null;pendingImport=null;pendingRelease=null;render();return;}if(paused||modal&&a!=='confirmImport'&&a!=='confirmNew'&&a!=='confirmRelease')return;
  if(a==='release'){if(state.battle||conflict)return;pendingRelease=state.reserve.find(c=>c.uid===button.dataset.uid);if(pendingRelease){modal='release';render();}return;}
  if(a==='confirmRelease'){if(!pendingRelease||state.battle||conflict)return;const uid=pendingRelease.uid;modal=null;pendingRelease=null;state=act(state,{type:'releaseReserve',uid});persist();render();return;}
  if(a==='start'){state=newGame(id);tab='world';persist();tone();render();return;}
  if(a==='openSettings'){tab='settings';render();return;}
  if(a==='backWelcome'){tab='world';render();return;}
  if(a==='export'){const blob=new Blob([serialize(state)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='starlight-adventure-v1.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(a==='new'){modal='new';render();return;}
  if(a==='confirmNew'){modal=null;state=null;tab='world';saved=false;notice='選好新夥伴後，才會覆寫原有存檔。';render();return;}
  if(a==='confirmImport'){state=pendingImport;pendingImport=null;modal=null;paused=false;tab='world';notice='已匯入冒險存檔。';persist();render();return;}
  if(a==='travel')dispatch({type:a,area:id});else if(a==='talk')dispatch({type:a,npc:id});else if(a==='buy')dispatch({type:a,item:id});else if(a==='attack')dispatch({type:a,move:Number(button.dataset.move)});else if(['lead','switch'].includes(a))dispatch({type:a,index});else if(a==='swapReserve')dispatch({type:a,index,teamIndex:state.active});else if(a)dispatch({type:a});
});
root.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>150000)throw new Error('存檔超過 150 KB，請選擇遊戲匯出的 JSON。');pendingImport=validateSave(await file.text());modal='import';}catch{notice='無法匯入：存檔無效、版本不相容或超過 150 KB。目前進度保持不變。';pendingImport=null;}render();});
root.addEventListener('keydown',e=>{if(!(paused||modal)||e.key!=='Tab')return;const nodes=[...root.querySelectorAll('.modal button')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;const map={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};if(map[e.key]&&state&&tab==='world'&&!state.battle&&!paused&&!modal){e.preventDefault();move(map[e.key]);}if(e.key==='Escape'&&state&&!modal){paused=!paused;audio?.suspend();render();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(state){paused=true;persist();}audio?.suspend();render();}});
window.addEventListener('pagehide',()=>{if(state)persist();audio?.suspend();});
window.addEventListener('storage',e=>{if(e.key===SAVE_KEY){conflict=true;paused=!!state;notice='其他分頁的冒險進度已改變。請重新整理以載入最新進度，避免覆寫。';render();}});
render();
